pair a=(1.38,-2.114), b=(1.76,-1.5);
path q =subpath(p, 1, 2);
path r=subpath(p,0,1);
path s=subpath(p,2,3);
draw(r);
draw(s);
draw(q, dashed);

label("$5$",midpoint((1.76,0)--(1.76,-2)),E);

[/asy]
